  "summary": "The code contains 4 issues, most critically an open redirect vulnerability and missing cookie security flags. Overall code health is poor due to lack of input validation, hardcoded configuration, and missing security best practices for session management.",
  "fixed_code": "const express = require(\"express\");\n\nconst app = express();\n\n/**\n * Completes the login process by setting a welcome cookie and redirecting the user.\n * @param {string} [req.query.returnTo] - The URL to redirect to after login.\n */\napp.get(\"/login/complete\", (req, res) => {\n    const allowed = ['/dashboard', '/profile', '/home'];\n    const target = allowed.includes(req.query.returnTo) ? req.query.returnTo : '/dashboard';\n    \n    res.cookie(\"seen_welcome\", \"1\", { \n        httpOnly: true, \n        secure: true, \n        sameSite: 'strict' \n    });\n    res.redirect(target);\n});\n\nconst PORT = process.env.PORT || 3000;\napp.listen(PORT, () => console.log(`Server running on port ${PORT}`));"
